// The rules, then clean(). False if anything is wrong (m_validation / m_error say what).
bool QiModel::runValidation(const QString &context, const QStringList &fields, bool uniqueKeys) {
    m_error.clear();
    QiModelMetaInfo *info = metaInfo();
    QiConnection conn = connection();
    QiValidator::Options o;
    o.context = context;
    o.fields = fields;
    o.uniqueKeys = uniqueKeys;
    m_validation = QiValidator::validate(this, info, &conn, o);
    const bool cleaned = fields.isEmpty() ? clean() : true;   // clean() looks at the whole record
    if (!cleaned) {
        if (!m_error.isValid())
            m_error = QiError(QiError::ValidationError, QStringLiteral("clean() rejected the record"));
        if (m_validation.isValid())
            m_validation.addError(QString(), m_error.text());
        return false;
    }
    if (!m_validation.isValid()) {
        m_error = QiError(QiError::ValidationError, m_validation.summary());
        return false;
    }
    return true;
}

QiValidation QiModel::validate(const QString &context) {
    runValidation(context, QStringList(), true);
    return m_validation;
}

QiValidation QiModel::validateFields(const QStringList &fields, const QString &context) {
    runValidation(context, fields, true);
    return m_validation;
}

bool QiModel::save(bool forceInsert,bool forceAllField) {
    const bool creating = forceInsert || id->isNull();
    if (!runValidation(creating ? QStringLiteral("create") : QStringLiteral("update"), QStringList(), false))
        return false;
    QiModelMetaInfo *info = metaInfo();
    Q_ASSERT(info);

    const bool created = creating;
    qiTouchTimestamps(info, this, created);

    QStringList fields = info->fieldNameList();
    QStringList nonNullFields;
    if (forceAllField) {

        nonNullFields = fields;

    } else {

    foreach (QString field , fields) {
        QVariant v = info->value(this,field);
        if (forceInsert && field == "id" ) // skip id field when forceInsert
            continue;

        if (!v.isNull() ) {
//            qDebug() << field;
            nonNullFields << field;
        }
    }

    }

    bool res ;

    QiSql sql = m_connection.sql();

    if (forceInsert || id->isNull() ) {
        res = sql.replaceInto(info,this,nonNullFields,true);
    } else {
        res = sql.replaceInto(info,this,nonNullFields,false);
    }

    if (!res)
        m_error = QiError(QiError::StatementError, sql.lastQuery().lastError().text());
    if (!res) {
        const QiFieldError fe = QiValidator::fromDatabaseError(m_error.text(), metaInfo());
        if (!fe.field.isEmpty())
            m_validation.add(fe);     // "UNIQUE constraint failed: user.email" -> email: is already taken
    }

    m_connection.setLastQuery(sql.lastQuery());

    if (res) {
        m_connection.notifyChanged(tableName());   // reactive: views watching this table refresh
        afterSave(created);
    }

    return res;
}

bool QiModel::upsert(const QStringList &conflictColumns, bool forceAllField) {
    m_error.clear();
    if (!clean()) {
        if (!m_error.isValid())
            m_error = QiError(QiError::ValidationError, QStringLiteral("clean() rejected the record"));
        return false;
    }
    QiModelMetaInfo *info = metaInfo();
    Q_ASSERT(info);

    const bool created = id->isNull();
    qiTouchTimestamps(info, this, created);

    QStringList fields = info->fieldNameList();
    QStringList writeFields;
    if (forceAllField) {
        writeFields = fields;
    } else {
        foreach (QString field , fields) {
            QVariant v = info->value(this,field);
            if (field == "id" && v.isNull()) // let the DB assign the id
                continue;
            if (!v.isNull())
                writeFields << field;
        }
    }

    QiSql sql = m_connection.sql();
    bool res = sql.upsertInto(info,this,writeFields,conflictColumns,id->isNull());

    if (!res)
        m_error = QiError(QiError::StatementError, sql.lastQuery().lastError().text());
    if (!res) {
        const QiFieldError fe = QiValidator::fromDatabaseError(m_error.text(), metaInfo());
        if (!fe.field.isEmpty())
            m_validation.add(fe);     // "UNIQUE constraint failed: user.email" -> email: is already taken
    }

    m_connection.setLastQuery(sql.lastQuery());

    if (res) {
        m_connection.notifyChanged(tableName());   // reactive
        afterSave(created);
    }

    return res;
}

bool QiModel::load(QiWhere where){
    m_error.clear();
    bool res = false;

    _QiMetaInfoQuery query( metaInfo() ,  m_connection);

    query = query.filter(where).limit(1);
    if (query.exec()){
        if (query.next()){
            res = query.recordTo(this);
            if (res)
                afterLoad();
        } else {
            m_error = QiError(QiError::NotFound, QStringLiteral("no matching record"));
        }
    } else {
        m_error = QiError(QiError::StatementError, query.lastQuery().lastError().text());
    }

    if (!res)
        id->clear();

    m_connection.setLastQuery(query.lastQuery());

    return res;
}

bool QiModel::remove() {
    m_error.clear();

    if (!beforeRemove()) {
        if (!m_error.isValid())
            m_error = QiError(QiError::ValidationError,
                              QStringLiteral("beforeRemove() vetoed the deletion"));
        return false;
    }

    QiModelMetaInfo *info = metaInfo();

    // Delete by the built-in "id" column when the schema has one; otherwise
    // (a QI_DECLARE_MODEL_NOID model) delete by the declared primary key —
    // which may be composite, so match on every primary-key column.
    QStringList pkFields = info->primaryKeyFields();
    const bool hasIdColumn = pkFields.contains(QStringLiteral("id"));

    QiWhere filter;
    bool haveFilter = false;

    if (hasIdColumn && !id->isNull()) {
        filter = QiWhere(QStringLiteral("id")) == id();
        haveFilter = true;
    } else {
        pkFields.removeAll(QStringLiteral("id"));
        bool ok = !pkFields.isEmpty();
        for (int i = 0; i < pkFields.size(); i++) {
            QVariant val = info->value(this, pkFields.at(i));
            if (val.isNull()) { ok = false; break; }
            QiWhere cond = QiWhere(pkFields.at(i)) == val;
            filter = (i == 0) ? cond : (filter && cond);
        }
        haveFilter = ok;
    }

    if (!haveFilter) {
        m_error = QiError(QiError::ValidationError,
                          QStringLiteral("cannot remove a record with no id / primary-key value"));
        return false;
    }

    _QiMetaInfoQuery query( info ,  m_connection);

    query = query.filter( filter );

    bool res = query.remove();
    if (res){
        id->clear();
    } else {
        m_error = QiError(QiError::StatementError, query.lastQuery().lastError().text());
    }

    m_connection.setLastQuery( query.lastQuery());

    if (res) {
        m_connection.notifyChanged(info->name());   // reactive
        afterRemove();
    }

    return res;
}

bool QiModel::softRemove() {
    m_error.clear();
    QiModelMetaInfo *info = metaInfo();
    if (!info->fieldNameList().contains(QStringLiteral("deletedAt"))) {
        setError(QiError(QiError::ValidationError,
                         QStringLiteral("softRemove() requires a 'deletedAt' field")));
        return false;
    }
    info->setValue(this, QStringLiteral("deletedAt"), QDateTime::currentDateTimeUtc());
    return save();   // writes the tombstone (and touches updatedAt)
}

bool QiModel::clean(){
    return true;
}

QiSharedList QiModel::initialData() const {
    return QiSharedList();
}

